'use strict';

// An untyped parameter of a package function binds at the argument's type,
// including the undefined a missing indexed read answers.
function isEmpty(ch) {
  return ch === undefined || ch === ' ' || ch === '\n';
}

// `charAt` reads past the end of the buffer; the wrapper passes that value
// to the untyped parameter, where Node's test for the miss decides.
class Cursor {
  constructor() {
    this.buffer = '';
    this.pos = 0;
  }
  setInput(src) {
    this.buffer = src;
    this.pos = 0;
  }
  charAt(n) {
    return this.buffer[this.pos + n];
  }
  isEmptyAt(n) {
    return isEmpty(this.charAt(n));
  }
}

exports.Cursor = Cursor;
